import { Children, cloneElement } from "react";
import { classNames } from "../../commonHelpers/classNames/classNames";
import { getAllowedComponent } from "../utils/getAllowedComponent";
import { updateGridStateFromProps } from "../utils/updateGridStateFromProps";
import { updateGridStateFromClassNames } from "../utils/updateGridStateFromClassNames";
import { mergeGridStates } from "../utils/mergeGridStates";
import { simplifyGridState } from "../utils/simplifyGridState";
import { fillGridState } from "../utils/fillGridState";
import { adaptGridState } from "../utils/adaptGridState";
import { convertStateToClasses } from "../utils/convertStateToClasses";
import { adjustGridState } from "../utils/adjustGridState";
import { getGridClasses } from "../utils/getGridClasses";
import { updateGridStateWithDefaultValues } from "../utils/updateGridStateWithDefaultValues";
const getEmptyGridItemState = () => ({
    gridLg: undefined,
    gridMd: undefined,
    gridSm: undefined,
    gridLgStart: undefined,
    gridMdStart: undefined,
    gridSmStart: undefined,
    lg: undefined,
    md: undefined,
    sm: undefined,
    lgStart: undefined,
    mdStart: undefined,
    smStart: undefined
});
/*
    1. Validation
    2. Convert props to grid item state
    3. Convert className to grid item state
    4. Merge states from props and className
    5. Simplify state: IGridItemFullState -> IGridItemBasicState
    6. Update state with default values (if no props or className provided; example - Card, depended on "size" argument)
    7. Adjust state (example: correct values to be in range of 1 to 12 for desktop)
    8. Fill state (to exclude empty values if possible)
    9. Adapt state (prevent overflowing, corner cases, etc.)
    10. Convert state to className
*/
export const useGridClasses = (children, childrenArr) => {
    Children.forEach(children, (child, indx) => {
        if (!child || typeof child === "string") {
            return;
        }
        const el = getAllowedComponent(child);
        if (!el) {
            return;
        }
        const stateFromProps = getEmptyGridItemState();
        const stateFromClassNames = getEmptyGridItemState();
        const mergedState = getEmptyGridItemState();
        updateGridStateFromProps(stateFromProps, el);
        updateGridStateFromClassNames(stateFromClassNames, el);
        mergeGridStates(stateFromProps, stateFromClassNames, mergedState);
        simplifyGridState(mergedState);
        updateGridStateWithDefaultValues(el, mergedState);
        adjustGridState(mergedState);
        fillGridState(mergedState);
        adaptGridState(mergedState);
        const gridClasses = convertStateToClasses(mergedState);
        const { restClasses } = getGridClasses(el.props.className || "");
        const itemClassName = classNames(["zen-grid__item", gridClasses.length ? "zen-grid__item--unset" : "", ...gridClasses, ...restClasses]);
        const clone = cloneElement(el, {
            key: el.props.id || el.key || indx,
            className: itemClassName
        });
        const prevElementIndex = childrenArr.findIndex((prevItem) => prevItem.key === clone.key);
        if (prevElementIndex !== -1) {
            childrenArr[prevElementIndex] = clone;
        }
        else {
            childrenArr.push(clone);
        }
    });
};
